class Solution {
    public List<String> twoEditWords(String[] queries,String[] dictionary){
        List<String> answer=new ArrayList<>();
        for(String query:queries)for(String word:dictionary){
            int differences=0;
            for(int i=0;i<query.length();i++)if(query.charAt(i)!=word.charAt(i))differences++;
            if(differences<=2){
                answer.add(query);
                break;
            }
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun twoEditWords(queries:Array<String>,dictionary:Array<String>):List<String>{
        return queries.filter{
            query->dictionary.any{
                word->query.indices.count{
                    query[it]!=word[it]
                }<=2
            }
        }
    }
}

code.cpp:
class Solution {
    public:vector<string> twoEditWords(vector<string>& queries,vector<string>& dictionary){
        vector<string> answer;
        for(string& query:queries)for(string& word:dictionary){
            int differences=0;
            for(int i=0;i<(int)query.size();++i)differences+=query[i]!=word[i];
            if(differences<=2){
                answer.push_back(query);
                break;
            }
        }
        return answer;
    }
};
